package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"
	"text/template"

	_ "github.com/lib/pq"
)

var db *sql.DB
var tmpl *template.Template

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	if connStr == "" {
		connStr = "postgres://appuser:apppass@db:5432/inventory?sslmode=disable"
	}
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
	tmpl = template.Must(template.New("results").Parse(`<html><body>
<h1>Inventory Search</h1>
<form method="GET" action="/search"><input name="category" /><input type="submit" /></form>
<table>{{range .}}<tr><td>{{.Name}}</td><td>{{.Price}}</td><td>{{.Stock}}</td></tr>{{end}}</table>
</body></html>`))
}

type Item struct {
	Name  string
	Price string
	Stock string
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	if category == "" {
		category = "all"
	}

	// Sanitize: remove semicolons to prevent stacked queries
	category = strings.ReplaceAll(category, ";", "")

	var query string
	if category == "all" {
		query = "SELECT name, price::text, stock::text FROM products ORDER BY name"
	} else {
		// Build query with category filter
		query = fmt.Sprintf("SELECT name, price::text, stock::text FROM products WHERE category = '%s' ORDER BY name", category)
	}

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	var items []Item
	for rows.Next() {
		var item Item
		if err := rows.Scan(&item.Name, &item.Price, &item.Stock); err != nil {
			continue
		}
		items = append(items, item)
	}

	w.Header().Set("Content-Type", "text/html")
	tmpl.Execute(w, items)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Listening on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
